WITH lines AS (SELECT id, customer_id, created_at, element FROM carts LATERAL VIEW EXPLODE(coupon_codes) x AS element) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, element, COUNT(CASE WHEN element = 'VIP' THEN 1 END) AS vip_count, COUNT(CASE WHEN element = 'BUNDLE' THEN 1 END) AS bundle_count, MIN(created_at) AS first_created_at, COUNT(*) AS event_count FROM lines GROUP BY 1, 2
